    public void accept_analysis_result(Control o,Settings data,long generation,bool loudness)
    {
        if(!analysis_provenance_current(o,data,generation))return;if(loudness&&analysis_current(o)&&Get(Dict(o,"_analysis_result"),"clip_id","").AsString()==Get(data,"clip_id","").AsString())Dict(o,"_analysis_result").Merge(data,true);else o.Set("_analysis_result",data.Duplicate(true));refresh_analysis(o);
    }
    public void toggle_effect_bypass(Control o)
    {
        var owner=effect_owner(o);var stack=Get(owner,"effects",new GArray()).AsGodotArray();SessionAction(o,"A/B effects",()=>{if(owner.ContainsKey("ab_enabled_mask")){var mask=owner["ab_enabled_mask"].AsGodotArray();for(int index=0;index<stack.Count;index++){var effect=stack[index].AsGodotDictionary();effect["enabled"]=index<mask.Count?mask[index].AsBool():Get(effect,"enabled",true).AsBool();}owner.Remove("ab_enabled_mask");}else{var mask=new GArray();foreach(var raw in stack){var effect=raw.AsGodotDictionary();mask.Add(Get(effect,"enabled",true).AsBool());effect["enabled"]=false;}owner["ab_enabled_mask"]=mask;}});
    }
    public void refresh_analysis(Control o)
    {
        var result=Dict(o,"_analysis_result");if(result.Count>0&&!analysis_current(o)){result=new Settings();o.Set("_analysis_result",result);}var panel=Field<Control>(o,"analysis_panel");clear(panel);var row=new HFlowContainer();panel.AddChild(row);ActionButton(row,"Analyze selected clip",()=>analyze_clip(o));ActionButton(row,"Review dialogue cleanup…",()=>o.Call("review_dialogue_batch"));Menu(o,row,"More tools",new GArray{"LEVELS & TIMING",Entry("Measure loudness (LUFS)",()=>measure_loudness(o)),Entry("Align two clips",()=>align_selected(o)),Entry("Match clip levels",()=>match_levels(o)),Entry("Dialogue ducking…",()=>ducking_dialog(o)),"RESTORATION",Entry("Review possible breaths…",()=>o.Call("review_breaths")),Entry("Learn noise profile",()=>sample_noise_profile(o)),"TRANSCRIPT",Entry("Transcribe locally",()=>Field<Node>(o,"_optional_tools").Call("transcribe")),Entry("Review saved transcript",()=>Field<Node>(o,"_optional_tools").Call("review_saved_transcript"))});var settings=Field<Node>(o,"_layout").Call("fold",panel,"cleanup_settings","Silence detection settings").As<Node>();foreach(var info in new[]{("_silence_threshold","Quiet threshold (dBFS)",-90.0,-6.0,1.0),("_silence_minimum","Minimum quiet (source s)",.05,10.0,.05),("_silence_keep","Retained pause (timeline s)",0.0,10.0,.01)}){string key=info.Item1;NumberAction(o,settings,info.Item2,o.Get(key).AsDouble(),info.Item3,info.Item4,info.Item5,value=>{o.Set(key,value);o.Call("_close_silence_review");});}label(settings,"PCM WAV analysis streams up to 2 hours from a source up to 24 hours. Other formats decode up to 600 seconds / 64 MiB. At most 2048 quiet regions. Quiet detection is not speech or breath recognition.");string F(string key,double fallback,int decimals=1)=>Get(result,key,fallback).AsDouble().ToString("F"+decimals,CultureInfo.InvariantCulture);if(result.ContainsKey("integrated_lufs"))label(panel,"Integrated "+F("integrated_lufs",0)+" LUFS · True peak "+F("true_peak_db",0)+" dBTP · Loudness range "+F("loudness_range",0)+" LU ("+Get(result,"method","").AsString()+")");if(result.Count==0){label(panel,"Analyze audio to review transient and silence detections, an estimated tempo, peak level and RMS level. Automatic edits remain undoable.");return;}string error=Get(result,"error","").AsString();if(error.Length>0){label(panel,error);return;}var actor=Document(o).Call("actor_for_clip",Get(result,"clip_id","")).AsGodotObject();label(panel,"Analyzed clip: "+(actor!=null?actor.Get("display_name").AsString():"Unavailable"));label(panel,"Peak "+F("peak_db",-120)+" dBFS  ·  RMS "+F("rms_db",-120)+" dBFS  ·  Tempo estimate "+F("tempo",0)+" BPM (confidence "+(Get(result,"confidence",0).AsDouble()*100).ToString("F0",CultureInfo.InvariantCulture)+"%)");if(result.ContainsKey("analyzed_start"))label(panel,Get(result,"analysis_method","Analysis").AsString()+" · source "+F("analyzed_start",0,3)+"–"+F("analyzed_end",0,3)+" s. Peak/RMS describe this analyzed range.");if(Get(result,"tempo_limited",false).AsBool())label(panel,"Tempo estimation is unavailable for PCM windows longer than 60 seconds; silence and attack detection still cover the displayed range.");label(panel,"RMS is not integrated LUFS. Tempo estimates may have half/double-time ambiguity; review before applying.");label(panel,Get(result,"transients",new GArray()).AsGodotArray().Count+" attacks · "+Get(result,"silences",new GArray()).AsGodotArray().Count+" quiet regions");var actions=new HFlowContainer();panel.AddChild(actions);ActionButton(actions,"Add attack markers",()=>add_attack_markers(o));ActionButton(actions,"Use estimated tempo",()=>{double tempo=Get(Dict(o,"_analysis_result"),"tempo",0).AsDouble();if(tempo>0)Session(o).Call("change_tempo",tempo);});ActionButton(actions,"Review silence cleanup",()=>o.Call("_apply_silences",o.Get("_silence_keep")));ActionButton(actions,"Learn selected noise profile",()=>sample_noise_profile(o));label(panel,"Open Review to keep/remove individual quiet regions and choose ripple scope.