    }
    public void ducking_dialog(Control o)
    {
        var owner=Session(o);var document=Document(o);long revision=owner.Get("revision").AsInt64();var dialog=window(o,"Dialogue ducking",new Vector2I(480,340));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var labels=new GArray();var ids=new GArray();foreach(var raw in Items(document,"tracks")){var track=raw.AsGodotDictionary();labels.Add(track["name"]);ids.Add(track["id"]);}if(labels.Count<2){windowNode.QueueFree();notice(o,"Create dialogue and background tracks first.");return;}var speech=ChoiceAction(o,host,"Dialogue",labels,labels[0].AsString(),_=>{});var music=ChoiceAction(o,host,"Background",labels,labels[1].AsString(),_=>{});var settings=new Settings{["amount"]=12.0,["threshold"]=-35.0,["attack"]=.08,["release"]=.35};foreach(var info in new[]{("amount",0.0,30.0,.1),("threshold",-70.0,-10.0,.1),("attack",.01,2.0,.01),("release",.02,4.0,.01)}){string key=info.Item1;NumberAction(o,host,key.Capitalize(),settings[key].AsDouble(),info.Item2,info.Item3,info.Item4,value=>settings[key]=value);}ActionButton(host,"Create editable volume automation",()=>{if(Session(o)!=owner||Document(o)!=document||owner.Get("revision").AsInt64()!=revision){notice(o,"The composition changed. Reopen Dialogue Ducking in the intended document.");return;}string speechId=ids[speech.Selected].AsString(),backgroundId=ids[music.Selected].AsString();if(speechId==backgroundId){notice(o,"Choose two different tracks.");return;}string problem=smart_track_problem(o,backgroundId);if(problem.Length>0){notice(o,problem);return;}long ownerId=unchecked((long)owner.GetInstanceId());var captures=new GArray();var clips=Items(document,"clips");var actors=Items(document,"actors");for(int index=0;index<clips.Count;index++){var values=Dict(actors[index].AsGodotObject(),"values");if(Get(values,"track_id","").AsString()==speechId)captures.Add(new Settings{["clip"]=clips[index].As<Resource>().Duplicate(false),["stream"]=workspace_source(Get(values,"audio")) is AudioStream backing?Variant.From(backing):default});}double baseline=Get(document.Call("track_for_id",backgroundId).AsGodotDictionary(),"volume_db",0).AsDouble();var config=settings.Duplicate(true);Work(o,"ducking",revision,job=>DuckingPoints(captures,config,baseline,backgroundId,ownerId,job));windowNode.QueueFree();});
    }
    private static Settings DuckingPoints(GArray captures,Settings settings,double baseline,string backgroundId,long ownerId,RefCounted job)
    {
        var points=new System.Collections.Generic.List<Settings>();using var analysis=new AudioAnalysisOperations();double threshold=settings["threshold"].AsDouble(),attack=settings["attack"].AsDouble(),release=settings["release"].AsDouble(),amount=settings["amount"].AsDouble();foreach(var raw in captures){if(job.Call("is_cancelled").AsBool())return new Settings{["error"]="Cancelled."};var capture=raw.AsGodotDictionary();var clip=capture["clip"].AsGodotObject();var stream=capture["stream"].As<AudioStream>();if(stream==null)continue;var result=analysis.analyze(stream,threshold,.1,job);var envelope=Get(result,"envelope",Array.Empty<float>()).AsFloat32Array();bool active=false;double offset=clip.Get("source_offset").AsDouble(),duration=clip.Get("duration").AsDouble(),speed=clip.Get("playback_speed").AsDouble(),start=clip.Get("start_time").AsDouble();for(int frame=0;frame<envelope.Length;frame++){double local=frame*.01;if(local<offset||local>offset+duration*speed)continue;bool now=envelope[frame]>Mathf.DbToLinear(threshold);double time=start+(local-offset)/speed;if(now&&!active){points.Add(new Settings{["time"]=Math.Max(0,time-attack),["value"]=baseline});points.Add(new Settings{["time"]=time,["value"]=baseline-amount});}if(!now&&active){points.Add(new Settings{["time"]=time,["value"]=baseline-amount});points.Add(new Settings{["time"]=time+release,["value"]=baseline});}active=now;}if(active){points.Add(new Settings{["time"]=start+duration,["value"]=baseline-amount});points.Add(new Settings{["time"]=start+duration+release,["value"]=baseline});}}points.Sort((a,b)=>a["time"].AsDouble().CompareTo(b["time"].AsDouble()));var ordered=new GArray();foreach(var point in points)ordered.Add(point);return new Settings{["track"]=backgroundId,["points"]=ordered,["owner_id"]=ownerId};
    }
